function OwnerEquipment(){const{token}=useAuth(),[items,setItems]=useState([]),[err,setErr]=useState('');const load=()=>api('/owner/equipment',{token}).then(setItems).catch(e=>setErr(e.message));useEffect(()=>{load()},[]);async function remove(id){if(confirm('Delete this equipment listing?')){try{await api(`/equipment/${id}`,{method:'DELETE',token});load()}catch(e){setErr(e.message)}}}async function toggleAvailability(item){try{await api("/equipment/"+item.id+"/availability-status",{method:"PATCH",token,body:{status:item.availability_status==="AVAILABLE"?"UNAVAILABLE":"AVAILABLE"}});load()}catch(e){setErr(e.message)}}return <><PageTitle title="My equipment" sub="Manage your listings and verification status." action={<Link to="/owner/equipment/new" className="btn"><Plus size={17}/> Add equipment</Link>}/>{err&&<div className="alert error">{err}</div>}<section className="panel">{items.length?items.map(e=><div className="field-card" key={e.id}><span className="stat-icon"><Tractor/></span><div><b>{e.brand} {e.model} · {e.equipment_type}</b><small>{e.village||'Village not set'} · {e.verification_status.replaceAll('_',' ')}</small></div><Link className="link-button" to={'/owner/equipment/'+e.id+'/edit'}>Edit</Link><button className="link-button" onClick={()=>toggleAvailability(e)}>{e.availability_status==="AVAILABLE"?"Pause":"Make available"}</button><button className="link-button danger-text" onClick={()=>remove(e.id)}>Delete</button></div>):<Empty title="No equipment listed" text="Add machinery and submit it for verification."/>}</section></>}
