function App(){
 const [token,setToken]=useState(localStorage.getItem('agriiigo')||'');
 const [user,setUser]=useState(()=>{try{return JSON.parse(localStorage.getItem('agriiigo-user'))}catch{return null}});
 useEffect(()=>{if(token&&!user)api('/auth/me',{token}).then(d=>{setUser(d.user);localStorage.setItem('agriiigo-user',JSON.stringify(d.user))}).catch(()=>{setToken('');localStorage.removeItem('agriiigo')})},[token]);
 const auth={token,setToken,user,setUser};
 const routes=[{path:'/',element:<Home/>},{path:'/demo',element:<DemoExperience/>},{path:'/login',element:<AuthPage mode="login"/>},{path:'/register',element:<AuthPage mode="register"/>},{path:'/forgot-password',element:<AuthPage mode="forgot"/>},{path:'/reset-password',element:<AuthPage mode="reset"/>}];
 for(const role of ['FARMER','OWNER','ADMIN']){const base=role.toLowerCase();routes.push(
  {path:`/${base}/dashboard`,element:<Protected role={role}><Dashboard/></Protected>},
  {path:`/${base}/profile`,element:<Protected role={role}><Profile/></Protected>},
  {path:`/${base}/bookings`,element:<Protected role={role}><Bookings/></Protected>},
  {path:`/${base}/bookings/:id`,element:<Protected role={role}><BookingDetail/></Protected>},
  {path:`/${base}/notifications`,element:<Protected role={role}><Notifications/></Protected>},
  {path:`/${base}/payments`,element:<Protected role={role}><GenericPage kind="payments"/></Protected>},
  {path:`/${base}/reviews`,element:<Protected role={role}><GenericPage kind="reviews"/></Protected>},
  {path:`/${base}/disputes`,element:<Protected role="ADMIN"><GenericPage kind="disputes"/></Protected>},
  {path:`/${base}/users`,element:<Protected role="ADMIN"><AdminUsers/></Protected>},
  {path:`/${base}/equipment`,element:<Protected role={role}>{role==='OWNER'?<OwnerEquipment/>:role==='ADMIN'?<AdminEquipment/>:<Equipment/>}</Protected>},
  {path:`/${base}/equipment/new`,element:<Protected role="OWNER"><EquipmentForm/></Protected>},
  {path:`/${base}/equipment/:id/edit`,element:<Protected role="OWNER"><EquipmentEdit/></Protected>},
  {path:`/${base}/equipment/:id`,element:<Protected role="FARMER"><Detail/></Protected>},
  {path:`/${base}/fields`,element:<Protected role="FARMER"><Fields/></Protected>},
  {path:`/${base}/availability`,element:<Protected role="OWNER"><Availability/></Protected>},
  {path:`/${base}/booking-requests`,element:<Protected role="OWNER"><Bookings/></Protected>},
  {path:`/${base}/active-bookings`,element:<Protected role="OWNER"><Bookings/></Protected>},
  {path:`/${base}/active-booking`,element:<Protected role="FARMER"><Bookings/></Protected>},
  {path:`/${base}/*`,element:<Protected role={role}><Dashboard/></Protected>}
 );}
 return <Auth.Provider value={auth}><RouterProvider router={createBrowserRouter(routes)}/></Auth.Provider>;
}
export default App;
